SELECT "users"."id" AS "users__id", "users"."name" AS "users__name", "users"."favoriteGame" AS "users__favoriteGame", "users"."age" AS "users__age", "users"."is_active" AS "users__is_active", "users"."rating" AS "users__rating", "users"."deletedAt" AS "users__deletedAt", "pets"."id" AS "pets__id", "pets"."owner_id" AS "pets__owner_id", "pets"."name" AS "pets__name" FROM "users" RIGHT JOIN "pets" ON "users"."id" = "pets"."owner_id"
